function prepareKeywordResearch(settings) {
  const {
    keywords,
    geoTargetConstants,
    language,
    network,
    customerId,
    managerId,
    pageSize,
    spreadsheetId,
    sheetName,
  } = settings;
  if (
    !Array.isArray(keywords) ||
    keywords.length < 1 ||
    keywords.length > 20 ||
    keywords.some(
      (keyword) => typeof keyword !== "string" || !keyword.trim() || keyword.length > 80,
    )
  ) {
    throw new Error("Enter 1 to 20 seed keywords");
  }
  if (
    !Array.isArray(geoTargetConstants) ||
    geoTargetConstants.length > 10 ||
    geoTargetConstants.some(
      (geo) => typeof geo !== "string" || !/^geoTargetConstants\/[1-9]\d{0,9}$/.test(geo),
    )
  ) {
    throw new Error("Enter up to 10 geoTargetConstants resource names");
  }
  if (
    typeof language !== "string" ||
    (language && !/^languageConstants\/[1-9]\d{0,9}$/.test(language))
  ) {
    throw new Error("Enter a languageConstants resource name or leave it empty");
  }
  if (!["GOOGLE_SEARCH", "GOOGLE_SEARCH_AND_PARTNERS"].includes(network))
    throw new Error("Choose a Google Ads search network");
  if (
    typeof customerId !== "string" ||
    !/^\d{10}$/.test(customerId) ||
    typeof managerId !== "string" ||
    (managerId && !/^\d{10}$/.test(managerId))
  ) {
    throw new Error("Enter the 10-digit Ads client ID and optional manager ID without hyphens");
  }
  if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > 500)
    throw new Error("Page size must be between 1 and 500");
  if (
    typeof spreadsheetId !== "string" ||
    !/^[A-Za-z0-9_-]{12,}$/.test(spreadsheetId) ||
    spreadsheetId === "YOUR_SPREADSHEET_ID" ||
    typeof sheetName !== "string" ||
    !sheetName.trim() ||
    sheetName.length > 100
  ) {
    throw new Error("Set the spreadsheet ID and sheet tab name");
  }
  return {
    endpoint:
      "https://googleads.googleapis.com/v26/customers/" + customerId + ":generateKeywordIdeas",
    headers: managerId ? { "login-customer-id": managerId } : {},
    body: {
      keywordSeed: { keywords: keywords.map((keyword) => keyword.trim()) },
      geoTargetConstants,
      ...(language ? { language } : {}),
      includeAdultKeywords: false,
      pageSize,
      keywordPlanNetwork: network,
    },
    spreadsheetId,
    sheetName,
    range: "'" + sheetName.replace(/'/g, "''") + "'!A:F",
  };
}

const settings = {
  keywords: ["desk lamp", "task lighting"],
  geoTargetConstants: ["geoTargetConstants/2840"],
  language: "languageConstants/1000",
  network: "GOOGLE_SEARCH",
  customerId: "YOUR_ADS_CUSTOMER_ID",
  managerId: "",
  pageSize: 200,
  spreadsheetId: "YOUR_SPREADSHEET_ID",
  sheetName: "Keyword Ideas",
};
return [{ json: prepareKeywordResearch(settings) }];

function keywordCount(value) {
  if (value == null) return "";
  if (typeof value === "number" && !Number.isSafeInteger(value))
    throw new Error("Google Ads returned an unsafe integer");
  if (typeof value !== "string" && typeof value !== "number")
    throw new Error("Google Ads returned an invalid integer");
  const digits = String(value);
  if (!/^\d{1,19}$/.test(digits) || BigInt(digits) > 9223372036854775807n) {
    throw new Error("Google Ads returned an invalid nonnegative int64");
  }
  return digits;
}

function bidDisplay(value) {
  const micros = keywordCount(value);
  if (micros === "") return "";
  const cents = (BigInt(micros) + 5000n) / 10000n;
  return (cents / 100n).toString() + "." + (cents % 100n).toString().padStart(2, "0");
}

function keywordRow(idea) {
  const keyword = idea?.text;
  const metrics = idea?.keywordIdeaMetrics ?? {};
  if (
    typeof keyword !== "string" ||
    !keyword.trim() ||
    keyword.length > 200 ||
    typeof metrics !== "object" ||
    Array.isArray(metrics)
  )
    throw new Error("Google Ads returned an invalid keyword idea");
  const competition = metrics.competition ?? "";
  if (!["", "UNSPECIFIED", "UNKNOWN", "LOW", "MEDIUM", "HIGH"].includes(competition)) {
    throw new Error("Google Ads returned an invalid competition value");
  }
  return [
    keyword,
    competition,
    keywordCount(metrics.avgMonthlySearches),
    keywordCount(metrics.competitionIndex),
    bidDisplay(metrics.lowTopOfPageBidMicros),
    bidDisplay(metrics.highTopOfPageBidMicros),
  ];
}

function collectKeywordPage(previous, response) {
  if (
    !response ||
    typeof response !== "object" ||
    Array.isArray(response) ||
    response.error ||
    (response.results !== undefined && !Array.isArray(response.results))
  ) {
    throw new Error("Google Ads did not return a keyword ideas page");
  }
  const page = response.results ?? [];
  const token = response.nextPageToken ?? "";
  if (
    typeof token !== "string" ||
    token.length > 4096 ||
    (token && previous.tokens.includes(token))
  ) {
    throw new Error("Google Ads returned an invalid or repeated next page token");
  }
  const rows = [...previous.rows, ...page.map(keywordRow)];
  const count = previous.count + 1;
  if (rows.length > 5000 || (token && count >= 20)) {
    throw new Error(
      "Keyword research exceeded 20 pages or 5000 rows. Narrow the seed or targeting and run again.",
    );
  }
  const reportedSize = keywordCount(response.totalSize);
  if (reportedSize && previous.totalSize && reportedSize !== previous.totalSize)
    throw new Error("Google Ads total changed between pages");
  const totalSize = reportedSize || previous.totalSize;
  if (
    totalSize &&
    (BigInt(rows.length) > BigInt(totalSize) ||
      (!token && BigInt(rows.length) !== BigInt(totalSize)))
  ) {
    throw new Error("Google Ads returned an incomplete or inconsistent results list");
  }
  if (new Set(rows.map((row) => row[0])).size !== rows.length)
    throw new Error("Google Ads repeated a keyword across pages");
  return {
    rows,
    count,
    tokens: token ? [...previous.tokens, token] : previous.tokens,
    totalSize,
    token,
  };
}

const plan = $("Set seed keywords and targeting").first().json;
let state = { rows: [], count: 0, tokens: [], totalSize: "", token: "" };
const pages = $input.all();
for (const item of pages) {
  if (item.json.statusCode !== 200) throw new Error("Google Ads keyword ideas failed");
  state = collectKeywordPage(state, item.json.body);
}
if (!pages.length || state.token) throw new Error("Google Ads pages are incomplete");
return [{ json: { ...plan, rows: state.rows, hasRows: state.rows.length > 0 } }];

function keywordSheetReceipt(receipt, expected, rows) {
  const { spreadsheetId, updatedRange, updatedRows, updatedData } = receipt ?? {};
  const split = typeof updatedRange === "string" ? updatedRange.lastIndexOf("!") : -1;
  const name = split < 0 ? "" : updatedRange.slice(0, split);
  const tab =
    name.startsWith("'") && name.endsWith("'") ? name.slice(1, -1).replace(/''/g, "'") : name;
  const coordinates =
    split < 0 ? null : /^A([1-9]\d*):[A-F]([1-9]\d*)$/.exec(updatedRange.slice(split + 1));
  const actual = updatedData?.values;
  if (
    spreadsheetId !== expected.spreadsheetId ||
    tab !== expected.sheetName ||
    !coordinates ||
    Number(coordinates[2]) - Number(coordinates[1]) + 1 !== rows.length ||
    updatedRows !== rows.length ||
    !Array.isArray(actual) ||
    actual.length !== rows.length ||
    !actual.every(
      (row, index) =>
        Array.isArray(row) &&
        row.length <= rows[index].length &&
        rows[index].every((cell, col) => (row[col] ?? "") === cell),
    )
  ) {
    throw new Error("Sheets did not confirm these rows. Check the target tab before retrying.");
  }
  return { spreadsheetId, updatedRange, appendedRows: updatedRows };
}

const plan = $("Check all pages and prepare rows").first().json;
const { body, statusCode } = $input.first().json;
if (statusCode !== 200 || body?.error)
  throw new Error("Sheets did not confirm the append. Check the target tab before retrying.");
return [
  {
    json: keywordSheetReceipt(
      { ...body.updates, spreadsheetId: body.spreadsheetId },
      plan,
      plan.rows,
    ),
  },
];
